import 'package:flutter/material.dart';import '../../core/app_state.dart';
class TrashPage extends StatelessWidget{const TrashPage({super.key});@override Widget build(BuildContext c){final s=AppStateScope.of(c);return Scaffold(appBar:AppBar(title:const Text('ゴミ箱')),body:s.trash.isEmpty?const Center(child:Text('ゴミ箱は空です')):ListView.builder(itemCount:s.trash.length,itemBuilder:(c,i){final x=s.trash[i];return ListTile(leading:const Icon(Icons.delete_outline),title:Text(x.title),subtitle:Text('${x.type} · ${x.deletedAt.year}/${x.deletedAt.month}/${x.deletedAt.day}'),trailing:PopupMenuButton<String>(onSelected:(v){if(v=='restore')s.restoreTrash(x);else s.deleteTrashForever(x);},itemBuilder:(_)=>const[PopupMenuItem(value:'restore',child:Text('復元')),PopupMenuItem(value:'delete',child:Text('完全削除'))]));}));}}
